        f1 = cards[0].cut("SURF_SURF_1") if "SURF_SURF_1" in CARD_LAYOUTS else _fixed_vals(cards[0], [10, 10, 10])
        surf1 = _ival(f1[0]) if len(f1) > 0 else 0
        surf2 = _ival(f1[1]) if len(f1) > 1 else 0
        iflag = _ival(f1[2]) if len(f1) > 2 else 0
        gap, fric = 0.0, 0.0
