            f2 = cards[1].cut("SURF_SURF_2") if "SURF_SURF_2" in CARD_LAYOUTS else _fixed_vals(cards[1], [20, 20])
            gap = _fval(f2[0], 0.0) if len(f2) > 0 else 0.0
