            fun_d4 = int(float(toks3[3])) if len(toks3) > 3 else 0
            fscale11 = float(toks3[4]) if len(toks3) > 4 else 1.0
            fscale22 = float(toks3[5]) if len(toks3) > 5 else 1.0
