            c2 = _safe_float(c4_card[1]) if len(c4_card) > 1 else 0.0
            c3 = _safe_float(c4_card[2]) if len(c4_card) > 2 else 0.0
            mmc_m = _safe_float(c4_card[3]) if len(c4_card) > 3 else 0.0
