            eps = _safe_float(t3[0]) if len(t3) > 0 else 0.0
            epst1 = _safe_float(t3[1]) if len(t3) > 1 else 0.0
            epst2 = _safe_float(t3[2]) if len(t3) > 2 else 0.0
